import React from 'react';
import {
  LinImageUpload,
  type LinImageUploadApi,
  type LinImageUploadItem,
} from '@linm-soft-org/linm-web-common-components';
import { filesEndpoint } from '../../../services/files/endpoint';
import { useAppToast } from '../../../hooks/useAppToast';
import {
  scykDetectionImageUploadConfig,
  scykDetectionImageUploadLabels,
} from '../../../config/scykDetectionImageUpload';
import type { MedicalIncidentAttachment } from '../../../models/MedicalIncident';
import {
  attachmentsToUploadItems,
  resolveUploadDisplayName,
  type IncidentUploadItem,
} from '../../MedicalIncidentFormPage/components/IncidentDocumentsTab';

export type DetectionUploadItem = IncidentUploadItem;
export { attachmentsToUploadItems, resolveUploadDisplayName };

export interface DetectionPhotosSectionProps {
  entityId?: string;
  items: LinImageUploadItem[];
  onChange: (items: LinImageUploadItem[]) => void;
  disabled?: boolean;
  title: string;
}

export function toAttachmentDtos(items: DetectionUploadItem[]): MedicalIncidentAttachment[] {
  return items
    .filter((item) => item.status === 'committed' && item.attachmentId)
    .map((item, index) => ({
      attachmentId: item.attachmentId!,
      objectKey: item.objectKey || '',
      fileName: resolveUploadDisplayName(item),
      contentType: item.contentType,
      sizeBytes: item.sizeBytes,
      sortOrder: index,
    }));
}

export const DetectionPhotosSection: React.FC<DetectionPhotosSectionProps> = ({
  entityId,
  items,
  onChange,
  disabled = false,
  title,
}) => {
  const toast = useAppToast();
  const fileErrorMessage = (err: unknown): string => (
    err instanceof Error && err.message
      ? err.message
      : scykDetectionImageUploadLabels.objectMissing
  );

  return (
    <div id="field-section-photos" data-testid="incident-detection-section-photos">
      <h3>{title}</h3>
      <LinImageUpload
        purpose={scykDetectionImageUploadConfig.purpose}
        product={scykDetectionImageUploadConfig.product}
        entityType={scykDetectionImageUploadConfig.entityType}
        entityId={entityId}
        items={items}
        onChange={onChange}
        minFiles={scykDetectionImageUploadConfig.minFiles}
        maxFiles={scykDetectionImageUploadConfig.maxFiles}
        maxBytes={scykDetectionImageUploadConfig.maxBytes}
        accept={scykDetectionImageUploadConfig.accept}
        disabled={disabled}
        confirmRemove={!disabled}
        showModalActions={false}
        labels={scykDetectionImageUploadLabels}
        client={{
          init: filesEndpoint.init,
          complete: async (uploadId, objectKey) => {
            try {
              await filesEndpoint.complete(uploadId, objectKey);
            } catch (err) {
              toast.error(fileErrorMessage(err));
              throw err;
            }
          },
          abort: filesEndpoint.abort,
          getObject: async (attachmentId: string) => {
            try {
              return await filesEndpoint.getObject(attachmentId);
            } catch (err) {
              toast.error(fileErrorMessage(err));
              throw err;
            }
          },
        } satisfies LinImageUploadApi}
        testId="incident-detection-field-photos"
      />
    </div>
  );
};
